parameters.jsCode:
function cos(a,b){let d=0,na=0,nb=0;for(let i=0;i<a.length;i++){d+=a[i]*b[i];na+=a[i]*a[i];nb+=b[i]*b[i];}return d/(Math.sqrt(na)*Math.sqrt(nb));}
const payload = JSON.parse($('Вопрос + объединённый индекс курсов').first().json.payload);
const resp = $input.first().json;
const qvec = resp.data[0].embedding;
const docs = payload.docs.map((d, i) => ({...d, embedding: resp.data[i + 1].embedding}));
const scored = docs.map(d => ({...d, cosine: cos(qvec, d.embedding)})).sort((a, b) => b.cosine - a.cosine);
const top = scored[0];
return [{json: {
  question: payload.question, course_id: payload.course_id, docs, qvec,
  unscoped_top_id: top.id, unscoped_top_course: top.course_id, unscoped_cosine: Number(top.cosine.toFixed(4)),
  unscoped_n_candidates: docs.length
}}];

function cos(a,b){let d=0,na=0,nb=0;for(let i=0;i<a.length;i++){d+=a[i]*b[i];na+=a[i]*a[i];nb+=b[i]*b[i];}return d/(Math.sqrt(na)*Math.sqrt(nb));}
const d = $input.first().json;
// Единственное отличие от узла «без скоупинга»: фильтр по course_id
// применён ДО ранжирования — чужой курс даже не входит в кандидатов.
const scopedDocs = d.docs.filter(doc => doc.course_id === d.course_id);
const scored = scopedDocs.map(doc => ({...doc, cosine: cos(d.qvec, doc.embedding)})).sort((a, b) => b.cosine - a.cosine);
const top = scored[0];
return [{json: {...d, docs: undefined, qvec: undefined,
  scoped_top_id: top.id, scoped_top_course: top.course_id,
  scoped_cosine: Number(top.cosine.toFixed(4)),
  scoped_n_candidates: scopedDocs.length
}}];

